const {vec} = NMath;
const {vertices} = await IO.loadMesh("/assets/bunny.obj");
if (vertices.length === 0) throw new Error("The bunny mesh contains no vertices");

const points = vertices.map(vertex => vec(...vertex));
const center = points.reduce((sum, point) => sum.add(point), vec.zero(3)).scale(1 / points.length);
const centered = points.map(point => point.sub(center));
const extent = centered.reduce((max, point) => Math.max(max, ...point.components.map(Math.abs)), 0);
if (!Number.isFinite(extent) || extent === 0) throw new Error("The bunny mesh has invalid bounds");
const normalized = centered.map(point => {
    const [x, y, z] = point.scale(1 / extent).components;
    return vec(z, x, y);
});

const neighbors = 8;
const smoothing = 64;
const radius = 0.05;
const model = HKmeans.new(normalized, {rho: 0.1, kmeansIter: 2}).fit();
const smoothUnion = (a, b) => HKmeans.CombinationFn.SMOOTH_UNION(a, b, smoothing);
const field = point => model.udf(vec(...point), neighbors, smoothUnion) - radius;

// Include the full zero-set support of the offset smooth union in the clip box.
const padding = radius + Math.log(neighbors) / smoothing + 0.01;
const min = [0, 1, 2].map(axis => Math.min(...normalized.map(point => point.components[axis])) - padding);
const max = [0, 1, 2].map(axis => Math.max(...normalized.map(point => point.components[axis])) + padding);
const ui = IO.sdfView(field, {
    width: 640/3, height: 480/3, scale: 3,
    epsilon: 0.002, maxIterations: 100,
    aabbClip: {min, max},
});
ui;
